"""
«Пришли мне на телефон …» — файл с компьютера прямо на телефон, откуда угодно.

  • С телефона: «пришли мне эссе про климат», «скинь SAT_practice.pdf», «пришли презентацию, над которой
    я работал вчера». Компьютер находит файл — по имени, по памяти компьютера или по смыслу содержимого —
    и на телефоне появляется кнопка «Открыть …».
  • За компьютером: «скинь это на телефон» — файл приходит уведомлением, нажал — открылся.
  • Ссылка — случайный ключ, живёт час; файл до 25 МБ. Через облако или напрямую, если телефон
    подключён к компьютеру.

    python apply_send_file.py
    python apply_send_file.py --rollback
"""
import base64
import hashlib
import os
import re
import shutil
import subprocess
import sys
import time

for _stream in (sys.stdout, sys.stderr):
    try:
        _stream.reconfigure(encoding="utf-8", errors="replace")
    except Exception:
        pass

ROOT = os.path.dirname(os.path.abspath(__file__))
ORIG = {'cloud/atlas_cloud.py': 'fe2f7d9e1a9d313f135a6ab03ba287a6ce26122d8558e7b8409e7092c7db1d02', 'core/pc_link.py': '07f58dddf122fbc42b73f6ecd8512d0989f81a925bcb775fad938eaebc93da39', 'phone/server.py': 'd59ac33e7d7372acb36217d7d5f61b55306d9e929758a6b3124d293bbdeabaf5', 'phone/static/index.html': '2fda098d836032471d7fcbed7e9fdcedcbee82b25d627f382cb75c9cfae98731', 'phone/static/sw.js': '8f278364327257e4d0f04cbf174da9e00b491ba0c314ecb2358262cf3d407755', 'skills/file_tasks.py': '3177da9d58917d3b6883d43764186e3e56a6be28fc4f7e744cf787ef28b441e7', 'tests/test_cloud_brain.py': '8a99d0a73d1c09c7927f0184c2083b095e2a5be2e432cf71ddcdae4cda7deec5', 'tests/test_file_tasks.py': 'a5ac0071814755fff59965824d6711da67d1d5a561c1941e106da5be9f0cf64c', 'tests/test_phone.py': 'f7a5fcc2ca5f7e5f25769b303f379adcb6f6e51086c3a695821976fa4fc52c49', 'core/file_drop.py': None}
NEW = {'cloud/atlas_cloud.py': '', 'core/pc_link.py': '', 'phone/server.py': '', 'phone/static/index.html': '', 'phone/static/sw.js': '', 'skills/file_tasks.py': '', 'tests/test_cloud_brain.py': '', 'tests/test_file_tasks.py': '', 'tests/test_phone.py': '', 'core/file_drop.py': ''}
TAG = "backup_sendfile_"


def p(rel):
    return os.path.join(ROOT, *rel.split("/"))


def restore(backup):
    for rel, h in ORIG.items():
        if h is None:
            if os.path.exists(p(rel)):
                os.remove(p(rel))
        else:
            shutil.copy2(os.path.join(backup, *rel.split("/")), p(rel))
    print(f"Вернул прежние файлы из {backup}.")


if "--rollback" in sys.argv:
    cands = sorted(d for d in os.listdir(ROOT) if d.startswith(TAG))
    if not cands:
        sys.exit("Резервной копии нет.")
    restore(p(cands[-1]))
    sys.exit(0)
if os.path.exists(p('core/file_drop.py')) and 'def resolve' in open(p('core/file_drop.py'), encoding="utf-8").read():
    sys.exit("Уже установлено.")

differ = []
for rel, h in ORIG.items():
    if h is None:
        if os.path.exists(p(rel)):
            differ.append(f"{rel} — уже есть такой файл")
        continue
    if not os.path.exists(p(rel)):
        differ.append(f"{rel} — нет файла")
        continue
    got = hashlib.sha256(open(p(rel), "rb").read().replace(b"\r\n", b"\n")).hexdigest()
    if got != h:
        differ.append(rel)
if differ:
    print("  ! отличаются от версии на GitHub: " + ", ".join(differ))
    sys.exit("Эти файлы у тебя изменены — ничего не тронул. Сделай git pull (или пришли мне вывод), потом запусти снова.")

backup = p(time.strftime(TAG + "%Y%m%d_%H%M%S"))
for rel, h in ORIG.items():
    if h is not None:
        os.makedirs(os.path.dirname(os.path.join(backup, *rel.split("/"))), exist_ok=True)
        shutil.copy2(p(rel), os.path.join(backup, *rel.split("/")))
print(f"Резервная копия: {backup}")
for rel, data in NEW.items():
    os.makedirs(os.path.dirname(p(rel)) or ROOT, exist_ok=True)
    with open(p(rel), "wb") as f:
        f.write(base64.b64decode(data))
print("  ✓ «пришли мне на телефон …» — файл с компьютера с кнопкой «Открыть» или уведомлением")

env = dict(os.environ, PYTHONIOENCODING="utf-8", PYTHONUTF8="1")
suites = [f for f in sorted(os.listdir(p("tests"))) if f.startswith("test_") and f.endswith(".py")]
for suite in suites:
    try:
        r = subprocess.run([sys.executable, p("tests/" + suite)], cwd=ROOT, capture_output=True, text=True,
                           encoding="utf-8", errors="replace", timeout=300, env=env)
        out, code = r.stdout + r.stderr, r.returncode
    except subprocess.TimeoutExpired:
        out, code = "✗ тесты не закончились за 5 минут", 1
    m = re.search(r"Тестов пройдено: (\d+) из (\d+)", out)
    good = code == 0 and m and m.group(1) == m.group(2)
    print(f"  {'✓' if good else '✗'} tests/{suite}: {m.group(0) if m else 'итоговой строки нет'}")
    if not good:
        lines = out.splitlines()
        for i, ln in enumerate(lines):
            if ln.strip().startswith("✗"):
                print("      " + "\n      ".join(x.rstrip() for x in lines[i:i + 7]))
        restore(backup)
        sys.exit("✗ Проверка не прошла — всё возвращено.")
print("\nГотово. Дальше: git add -A, git commit, git push — Render обновится сам; перезапусти Atlas на компьютере.")
print("На телефоне закрой и открой Atlas, потом: «пришли мне на телефон …» (файл, который точно есть на компе).")

